// One shape for both channels: { channel, session_id, text, reply_to, customer_name }
const j = $input.first().json;
if (j.action && j.action !== 'sendMessage') return []; // e.g. the chat widget asking to reload an old session
if (j.chatInput !== undefined) {
  return [{ json: { channel: 'website', session_id: 'web-' + j.sessionId, text: String(j.chatInput || '').slice(0, 2000), reply_to: '', customer_name: '' } }];
}
const msg = (j.messages || [])[0];
if (!msg) return []; // delivery/read receipts: nothing to answer
const contact = (j.contacts || [])[0] || {};
let text = '';
if (msg.type === 'text') text = msg.text?.body || '';
else if (msg.type === 'button') text = msg.button?.text || '';
else if (msg.type === 'interactive') text = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
else text = `(The customer sent a ${msg.type} message, which you cannot open. Politely ask them to type their question.)`;
return [{ json: { channel: 'whatsapp', session_id: 'wa-' + msg.from, text: text.slice(0, 2000), reply_to: msg.from, customer_name: contact.profile?.name || '' } }];

// Turns every row of the FAQ sheet into "Topic: answer" lines for the assistant.
const lines = [];
for (const { json: row } of $input.all()) {
  const values = Object.entries(row).filter(([k, v]) => k !== 'row_number' && String(v ?? '').trim() !== '');
  if (!values.length) continue;
  lines.push(values.map(([k, v]) => String(v).trim()).join(': '));
}
return [{ json: { ...$('Read the message').first().json, knowledge: lines.join('\n') || '(The FAQ sheet is empty.)' } }];

